ST.xhtml:p:
F_PowerOff(CLK := g_bDriveEnable);
IF F_PowerOff.Q THEN
  bFPowerEnable := FALSE;
END_IF;


g_FPower.Enable := bFPowerEnable;
g_FPower.EnablePosition := NOT g_bFAxisPosLimit;
g_FPower.EnableNegative := NOT g_bFAxisNegLimit;

(*NC轴在选择限位回零的情况下，需在回零过程中，屏蔽掉相应的限位报警*)
IF  g_FAxis.NCTOPLC.AXISSTATE =5 AND g_nFAxisHomeSignal <>0 AND g_nFHomeMode <> 1 THEN
  g_FPower.EnablePosition :=TRUE;
  g_FPower.EnableNegative := TRUE;
END_IF;


IF g_FPower.Error THEN
  bFPowerEnable := false;
END_IF;
IF ABS(g_FAxis.NCTOPLC.ACTPOS - g_FAxis.NCTOPLC.SETPOS) > g_fFAxisMaxPosError THEN
  g_bFAxisPosErrorAlarm := TRUE;
ELSE
  g_bFAxisPosErrorAlarm := FALSE;
END_IF;
